function throttle(fn, ms) {
  let waiting = false;
  let last = null;
  const run = (x) => {
    fn(x);
    waiting = true;
    setTimeout(() => {
      waiting = false;
      if (last !== null) {
        const next = last;
        last = null;
        run(next);
      }
    }, ms);
  };
  return (x) => (waiting ? (last = x) : run(x));
}

const t = throttle((x) => console.log(x), 40);
t("a");
t("b");
t("c");
setTimeout(() => t("d"), 60);
